import type { CEFRLevel } from "./learner";

export interface GrammarDrillExtra {
  id: string; // "g-<bandslug>-x<N>-<tag>" — unique; must not collide with app/(app)/grammar/page.tsx ids
  level: CEFRLevel; // "Pre-A1" | "A1" | "A2" | "B1" | "B2" | "C1" | "C2"
  pattern: string; // short pattern label
  explanation: string; // 1-2 sentence teaching note
  sentence: string; // contains exactly one ___ gap, natural UK English
  answer: string; // MUST be exactly one of options
  options: string[]; // 2-4 plausible options incl. the answer
  extra: string[]; // additional distractors shown with options (usually [])
}

export const GRAMMAR_DRILLS_EXTRA: GrammarDrillExtra[] = [
  // Pre-A1 — be, articles, this/that, possessives, plurals, imperatives, numbers, can, simple questions
  { id: "g-prea1-x1-am-years", level: "Pre-A1", pattern: "am / is / are", explanation: "With I, the verb is always am.", sentence: "I ___ seven years old.", answer: "am", options: ["am", "is"], extra: [] },
  { id: "g-prea1-x2-are-spain", level: "Pre-A1", pattern: "am / is / are", explanation: "You, we and they take are.", sentence: "We ___ from Spain.", answer: "are", options: ["are", "is"], extra: [] },
  { id: "g-prea1-x3-are-you-happy", level: "Pre-A1", pattern: "Be in yes/no questions", explanation: "Questions with be put the verb first: Are you…?", sentence: "___ you happy today?", answer: "Are", options: ["Are", "Is"], extra: [] },
  { id: "g-prea1-x4-is-dad-doctor", level: "Pre-A1", pattern: "am / is / are", explanation: "He, she and it take is, even for family members.", sentence: "My dad ___ a doctor.", answer: "is", options: ["is", "am"], extra: [] },
  { id: "g-prea1-x5-a-big-cat", level: "Pre-A1", pattern: "a / an", explanation: "Use a before a consonant sound and an before a vowel sound.", sentence: "It is ___ big cat.", answer: "a", options: ["a", "an"], extra: [] },
  { id: "g-prea1-x6-an-egg", level: "Pre-A1", pattern: "a / an", explanation: "Egg starts with a vowel sound, so we say an egg.", sentence: "I want ___ egg for breakfast.", answer: "an", options: ["an", "a"], extra: [] },
  { id: "g-prea1-x7-this-ball", level: "Pre-A1", pattern: "this / these", explanation: "This is for one thing near you; these is for more than one.", sentence: "___ is my ball.", answer: "This", options: ["This", "These"], extra: [] },
  { id: "g-prea1-x8-those-stars", level: "Pre-A1", pattern: "that / those", explanation: "Those is for many things far away.", sentence: "Look at ___ stars in the sky.", answer: "those", options: ["those", "this"], extra: [] },
  { id: "g-prea1-x9-these-shoes", level: "Pre-A1", pattern: "this / these", explanation: "Shoes are two things, so we use these.", sentence: "___ are my new shoes.", answer: "These", options: ["These", "This"], extra: [] },
  { id: "g-prea1-x10-that-school", level: "Pre-A1", pattern: "this / that", explanation: "That points to one thing far away.", sentence: "___ is our school over there.", answer: "That", options: ["That", "These"], extra: [] },
  { id: "g-prea1-x11-my-brother", level: "Pre-A1", pattern: "my / your", explanation: "My shows something belongs to me.", sentence: "This is ___ brother. I love him.", answer: "my", options: ["my", "your"], extra: [] },
  { id: "g-prea1-x12-her-bike", level: "Pre-A1", pattern: "his / her", explanation: "Her shows something belongs to a girl or woman.", sentence: "Sara has a red bike. ___ bike is fast.", answer: "Her", options: ["Her", "His"], extra: [] },
  { id: "g-prea1-x13-his-dog", level: "Pre-A1", pattern: "his / her", explanation: "His shows something belongs to a boy or man.", sentence: "Tom has a dog. ___ dog is black.", answer: "His", options: ["His", "Her"], extra: [] },
  { id: "g-prea1-x14-your-name", level: "Pre-A1", pattern: "my / your", explanation: "Your shows something belongs to the person you speak to.", sentence: "Hello, what is ___ name?", answer: "your", options: ["your", "his"], extra: [] },
  { id: "g-prea1-x15-two-cats", level: "Pre-A1", pattern: "Regular plurals", explanation: "After two we use the plural noun, which usually ends in -s.", sentence: "I have two ___ at home. (cat)", answer: "cats", options: ["cats", "cat"], extra: [] },
  { id: "g-prea1-x16-four-wheels", level: "Pre-A1", pattern: "Regular plurals", explanation: "For more than one, most nouns add -s.", sentence: "The bus has four ___. (wheel)", answer: "wheels", options: ["wheels", "wheel"], extra: [] },
  { id: "g-prea1-x17-sit-down", level: "Pre-A1", pattern: "Imperatives", explanation: "Instructions use the base verb with no -s and no subject.", sentence: "___ down, please.", answer: "Sit", options: ["Sit", "Sits"], extra: [] },
  { id: "g-prea1-x18-open-window", level: "Pre-A1", pattern: "Imperatives", explanation: "Use the plain verb form to give an instruction.", sentence: "___ the window, please. It is hot.", answer: "Open", options: ["Open", "Opens"], extra: [] },
  { id: "g-prea1-x19-dont-run", level: "Pre-A1", pattern: "Negative imperatives", explanation: "Don't + verb tells someone not to do something.", sentence: "___ run in the classroom.", answer: "Don't", options: ["Don't", "Doesn't"], extra: [] },
  { id: "g-prea1-x20-one-brother", level: "Pre-A1", pattern: "one / two", explanation: "One means a single person or thing.", sentence: "I have ___ brother and two sisters.", answer: "one", options: ["one", "two"], extra: [] },
  { id: "g-prea1-x21-two-candles", level: "Pre-A1", pattern: "one / two", explanation: "Two is the number after one.", sentence: "My birthday cake has ___ candles. (2)", answer: "two", options: ["two", "one"], extra: [] },
  { id: "g-prea1-x22-can-swim", level: "Pre-A1", pattern: "I can / can't", explanation: "Can shows ability and never takes -s.", sentence: "I ___ swim very fast.", answer: "can", options: ["can", "can't"], extra: [] },
  { id: "g-prea1-x23-cant-walk", level: "Pre-A1", pattern: "I can / can't", explanation: "Can't shows something is not possible for you yet.", sentence: "The baby ___ walk, but he can crawl.", answer: "can't", options: ["can't", "can"], extra: [] },
  { id: "g-prea1-x24-can-you-ride", level: "Pre-A1", pattern: "Can you…? questions", explanation: "Ability questions start with Can: Can you swim?", sentence: "___ you ride a bike?", answer: "Can", options: ["Can", "Are"], extra: [] },
  { id: "g-prea1-x25-its-pencil", level: "Pre-A1", pattern: "What is it? It's…", explanation: "We answer questions about one thing with It's…", sentence: "What is this? ___ a pencil.", answer: "It's", options: ["It's", "They're"], extra: [] },
  { id: "g-prea1-x26-what-colour", level: "Pre-A1", pattern: "What colour…? questions", explanation: "What asks about things; use What colour to ask about colour.", sentence: "___ colour is your bag?", answer: "What", options: ["What", "Where"], extra: [] },
  { id: "g-prea1-x27-is-mum-teacher", level: "Pre-A1", pattern: "Be in yes/no questions", explanation: "With he, she or it, questions start with Is.", sentence: "___ your mum a teacher?", answer: "Is", options: ["Is", "Are"], extra: [] },
  // A1 — present simple, prepositions, some/any, there is/are, can, object pronouns, like + -ing, would like
  { id: "g-a1-x1-live-manchester", level: "A1", pattern: "Present simple: I/you/we/they", explanation: "With I, you, we and they the verb has no -s.", sentence: "My parents ___ in Manchester.", answer: "live", options: ["live", "lives"], extra: [] },
  { id: "g-a1-x2-studies-college", level: "A1", pattern: "Present simple: he/she + verb-s", explanation: "With he, she or it add -s; verbs ending in consonant + y change to -ies.", sentence: "Maria ___ English at college. (study)", answer: "studies", options: ["studies", "study"], extra: [] },
  { id: "g-a1-x3-dont-eat-meat", level: "A1", pattern: "Present simple negative", explanation: "With I, you, we and they use don't + base verb.", sentence: "I ___ eat meat, but I eat fish.", answer: "don't", options: ["don't", "doesn't"], extra: [] },
  { id: "g-a1-x4-does-brother-play", level: "A1", pattern: "Present simple questions", explanation: "With he, she or it, questions use Does + base verb.", sentence: "___ your brother play football at the weekend?", answer: "Does", options: ["Does", "Do"], extra: [] },
  { id: "g-a1-x5-do-you-tea", level: "A1", pattern: "Present simple questions", explanation: "With I, you, we and they, questions use Do.", sentence: "___ you want a cup of tea?", answer: "Do", options: ["Do", "Does"], extra: [] },
  { id: "g-a1-x6-does-homework", level: "A1", pattern: "Present simple: he/she + verb-s", explanation: "She takes does for the verb do: she always does her homework.", sentence: "She always ___ her homework after dinner. (do)", answer: "does", options: ["does", "do"], extra: [] },
  { id: "g-a1-x7-in-april", level: "A1", pattern: "in / on / at for time", explanation: "in goes with months and years.", sentence: "My birthday is ___ April.", answer: "in", options: ["in", "on", "at"], extra: [] },
  { id: "g-a1-x8-at-seven-thirty", level: "A1", pattern: "in / on / at for time", explanation: "at goes with clock times.", sentence: "The film starts ___ seven thirty.", answer: "at", options: ["at", "in", "on"], extra: [] },
  { id: "g-a1-x9-under-bed", level: "A1", pattern: "Prepositions of place", explanation: "Under means directly below something.", sentence: "My shoes are ___ the bed.", answer: "under", options: ["under", "in"], extra: [] },
  { id: "g-a1-x10-next-to-bank", level: "A1", pattern: "Prepositions of place", explanation: "Next to means beside, at the side of.", sentence: "The chemist is ___ the bank, right beside it.", answer: "next to", options: ["next to", "between"], extra: [] },
  { id: "g-a1-x11-some-butter", level: "A1", pattern: "some / any", explanation: "In positive sentences we usually use some.", sentence: "There is ___ butter in the fridge.", answer: "some", options: ["some", "any"], extra: [] },
  { id: "g-a1-x12-any-money", level: "A1", pattern: "some / any", explanation: "After haven't got we use any.", sentence: "I haven't got ___ money with me.", answer: "any", options: ["any", "some"], extra: [] },
  { id: "g-a1-x13-there-is-park", level: "A1", pattern: "there is / there are", explanation: "There is goes with one thing (singular).", sentence: "___ a big park near my house.", answer: "There is", options: ["There is", "There are"], extra: [] },
  { id: "g-a1-x14-there-are-museums", level: "A1", pattern: "there is / there are", explanation: "There are goes with more than one thing (plural).", sentence: "___ two museums in our town.", answer: "There are", options: ["There are", "There is"], extra: [] },
  { id: "g-a1-x15-can-ride", level: "A1", pattern: "can for ability", explanation: "Can never changes: she can, never she cans.", sentence: "My little sister ___ already ride a bike.", answer: "can", options: ["can", "cans"], extra: [] },
  { id: "g-a1-x16-cant-hear", level: "A1", pattern: "can for ability", explanation: "Can't is the negative of can.", sentence: "Sorry, I ___ hear you. The line is bad.", answer: "can't", options: ["can't", "can"], extra: [] },
  { id: "g-a1-x17-help-me", level: "A1", pattern: "Object pronouns: me", explanation: "After a verb we use object pronouns: me, not I.", sentence: "Can you help ___? I can't lift this box.", answer: "me", options: ["me", "I"], extra: [] },
  { id: "g-a1-x18-know-him", level: "A1", pattern: "Object pronouns: him", explanation: "After a verb, he becomes him.", sentence: "That's Tom. Do you know ___?", answer: "him", options: ["him", "he"], extra: [] },
  { id: "g-a1-x19-one-of-them", level: "A1", pattern: "Object pronouns: them", explanation: "After a preposition we use them, not they.", sentence: "I like these cakes. Can I have one of ___?", answer: "them", options: ["them", "they"], extra: [] },
  { id: "g-a1-x20-see-her", level: "A1", pattern: "Object pronouns: her", explanation: "After a verb, she becomes her.", sentence: "Sue is my best friend. I see ___ every day.", answer: "her", options: ["her", "she"], extra: [] },
  { id: "g-a1-x21-like-listening", level: "A1", pattern: "like + -ing", explanation: "After like, love and hate we use the -ing form.", sentence: "I like ___ to music on the bus. (listen)", answer: "listening", options: ["listening", "listen"], extra: [] },
  { id: "g-a1-x22-loves-swimming", level: "A1", pattern: "like + -ing", explanation: "Verbs of preference are followed by verb + -ing.", sentence: "She loves ___ early. (swim)", answer: "swimming", options: ["swimming", "swim"], extra: [] },
  { id: "g-a1-x23-would-like-sandwich", level: "A1", pattern: "would like for offers", explanation: "Would you like…? politely offers something now.", sentence: "___ you like a sandwich?", answer: "Would", options: ["Would", "Do"], extra: [] },
  { id: "g-a1-x24-would-book-table", level: "A1", pattern: "would like to + verb", explanation: "would like to means want to, politely.", sentence: "I ___ like to book a table for two.", answer: "would", options: ["would", "will"], extra: [] },
  { id: "g-a1-x25-wouldnt-come", level: "A1", pattern: "would like negatives", explanation: "The negative of would like is wouldn't like.", sentence: "He ___ like to come; he is too tired.", answer: "wouldn't", options: ["wouldn't", "doesn't"], extra: [] },
  { id: "g-a1-x26-gives-us", level: "A1", pattern: "Object pronouns: us", explanation: "After a verb, we becomes us.", sentence: "Our teacher gives ___ homework every Friday.", answer: "us", options: ["us", "we"], extra: [] },
  // A2 — past simple, comparatives/superlatives, going to, will, countables, adverbs of manner, present continuous vs present simple, have to/must
  { id: "g-a2-x1-went-greece", level: "A2", pattern: "Past simple irregulars", explanation: "Go is irregular: go → went, never goed.", sentence: "Last summer we ___ to Greece. (go)", answer: "went", options: ["went", "goed", "gone"], extra: [] },
  { id: "g-a2-x2-ate-pasta", level: "A2", pattern: "Past simple irregulars", explanation: "Eat is irregular: eat → ate, with no -ed.", sentence: "She ___ a big plate of pasta. (eat)", answer: "ate", options: ["ate", "eated", "eaten"], extra: [] },
  { id: "g-a2-x3-watched-tv", level: "A2", pattern: "Past simple regulars", explanation: "Regular past verbs add -ed.", sentence: "The children ___ TV after school. (watch)", answer: "watched", options: ["watched", "watch"], extra: [] },
  { id: "g-a2-x4-stopped-bus", level: "A2", pattern: "Past simple regulars", explanation: "Short verbs ending consonant-vowel-consonant double the last letter: stop → stopped.", sentence: "The bus ___ suddenly. (stop)", answer: "stopped", options: ["stopped", "stoped"], extra: [] },
  { id: "g-a2-x5-didnt-sleep", level: "A2", pattern: "Past simple negative", explanation: "After didn't the verb returns to its base form.", sentence: "I ___ sleep well last night.", answer: "didn't", options: ["didn't", "don't"], extra: [] },
  { id: "g-a2-x6-did-enjoy", level: "A2", pattern: "Past simple questions", explanation: "Past simple questions use Did + base verb.", sentence: "___ you enjoy the concert?", answer: "Did", options: ["Did", "Was"], extra: [] },
  { id: "g-a2-x7-cheaper-shirt", level: "A2", pattern: "Comparatives", explanation: "Short adjectives form the comparative with -er + than.", sentence: "The white shirt is ___ than the blue one. (cheap)", answer: "cheaper", options: ["cheaper", "more cheap"], extra: [] },
  { id: "g-a2-x8-more-difficult", level: "A2", pattern: "Comparatives", explanation: "Longer adjectives take more + adjective + than.", sentence: "Physics is ___ than chemistry for me. (difficult)", answer: "more difficult", options: ["more difficult", "difficulter"], extra: [] },
  { id: "g-a2-x9-hottest-day", level: "A2", pattern: "Superlatives", explanation: "Short adjectives form the superlative with the + adjective + -est; hot doubles its t.", sentence: "It was ___ day of the year. (hot)", answer: "the hottest", options: ["the hottest", "the most hot"], extra: [] },
  { id: "g-a2-x10-best-cake", level: "A2", pattern: "Irregular superlatives", explanation: "Good is irregular: good → better → the best.", sentence: "This is ___ cake I have ever made.", answer: "the best", options: ["the best", "the goodest"], extra: [] },
  { id: "g-a2-x11-goingto-clouds", level: "A2", pattern: "be going to (evidence)", explanation: "When present evidence shows something is about to happen, use be going to.", sentence: "Look at those clouds — it ___ rain soon.", answer: "is going to", options: ["is going to", "is"], extra: [] },
  { id: "g-a2-x12-goingto-married", level: "A2", pattern: "be going to (plans)", explanation: "be going to + verb expresses plans already decided.", sentence: "They ___ get married in September.", answer: "are going to", options: ["are going to", "was going to"], extra: [] },
  { id: "g-a2-x13-will-win", level: "A2", pattern: "will for predictions", explanation: "Use will + base verb for predictions and opinions about the future.", sentence: "I think England ___ win the match.", answer: "will", options: ["will", "wills"], extra: [] },
  { id: "g-a2-x14-wont-fail", level: "A2", pattern: "will negatives", explanation: "won't is the short form of will not.", sentence: "Don't worry — you ___ fail the test.", answer: "won't", options: ["won't", "don't"], extra: [] },
  { id: "g-a2-x15-much-sugar", level: "A2", pattern: "much / many", explanation: "Sugar is uncountable, so it takes much.", sentence: "How ___ sugar do you take?", answer: "much", options: ["much", "many"], extra: [] },
  { id: "g-a2-x16-few-eggs", level: "A2", pattern: "a few / a little", explanation: "a few goes with countable plurals like eggs.", sentence: "There are only a ___ eggs left.", answer: "few", options: ["few", "little"], extra: [] },
  { id: "g-a2-x17-little-time", level: "A2", pattern: "a few / a little", explanation: "a little goes with uncountable nouns like time.", sentence: "Can I have a ___ more time?", answer: "little", options: ["little", "few"], extra: [] },
  { id: "g-a2-x18-sings-beautifully", level: "A2", pattern: "Adverbs of manner", explanation: "Most adverbs of manner are adjective + -ly.", sentence: "She sings ___. (beautiful)", answer: "beautifully", options: ["beautifully", "beautiful"], extra: [] },
  { id: "g-a2-x19-drive-carefully", level: "A2", pattern: "Adverbs of manner", explanation: "The adverb carefully describes how the action is done.", sentence: "Please drive ___ — the roads are icy. (careful)", answer: "carefully", options: ["carefully", "careful"], extra: [] },
  { id: "g-a2-x20-works-hard", level: "A2", pattern: "hard / hardly", explanation: "Hard is both adjective and adverb; hardly means almost not at all.", sentence: "He works ___ and never complains.", answer: "hard", options: ["hard", "hardly"], extra: [] },
  { id: "g-a2-x21-is-sleeping", level: "A2", pattern: "Present continuous (now)", explanation: "Actions happening at this moment take am/is/are + -ing.", sentence: "Be quiet! The baby ___ upstairs. (sleep)", answer: "is sleeping", options: ["is sleeping", "sleeps"], extra: [] },
  { id: "g-a2-x22-leaves-six-thirty", level: "A2", pattern: "Present simple (timetables)", explanation: "Fixed timetables use the present simple, not the continuous.", sentence: "My train ___ at half past six every morning. (leave)", answer: "leaves", options: ["leaves", "is leaving"], extra: [] },
  { id: "g-a2-x23-am-staying-week", level: "A2", pattern: "Present continuous (temporary)", explanation: "Temporary situations around now take the present continuous.", sentence: "I ___ with my aunt this week while my flat is painted. (stay)", answer: "am staying", options: ["am staying", "stay"], extra: [] },
  { id: "g-a2-x24-have-to-report", level: "A2", pattern: "have to for obligation", explanation: "have to + base verb expresses obligation; with I it stays have.", sentence: "I ___ finish this report before five. (obligation)", answer: "have to", options: ["have to", "has to"], extra: [] },
  { id: "g-a2-x25-mustnt-park", level: "A2", pattern: "mustn't for prohibition", explanation: "mustn't means it is forbidden — don't have to means it is not necessary.", sentence: "You ___ park here — it's for buses only.", answer: "mustn't", options: ["mustn't", "don't have to"], extra: [] },
  { id: "g-a2-x26-dont-have-to-early", level: "A2", pattern: "don't have to (no obligation)", explanation: "don't have to means it is not necessary, not that it is forbidden.", sentence: "It's Saturday, so I ___ get up early.", answer: "don't have to", options: ["don't have to", "mustn't"], extra: [] },
  // B1 — present perfect vs past simple, for/since, first conditional, relatives, second conditional, used to, past continuous, both/either/neither, indirect questions
  { id: "g-b1-x1-have-ever-been", level: "B1", pattern: "Present perfect: life experience", explanation: "ever with an unfinished life takes the present perfect, not the past simple.", sentence: "___ you ever been to Ireland?", answer: "Have", options: ["Have", "Did"], extra: [] },
  { id: "g-b1-x2-just-finished", level: "B1", pattern: "Present perfect: just", explanation: "just + past participle shows a very recent action.", sentence: "I've just ___ my essay. (finish)", answer: "finished", options: ["finished", "finish"], extra: [] },
  { id: "g-b1-x3-saw-film", level: "B1", pattern: "Past simple: finished time", explanation: "A finished time phrase like last year forces the past simple.", sentence: "I ___ that film last year. (see)", answer: "saw", options: ["saw", "have seen"], extra: [] },
  { id: "g-b1-x4-not-yet", level: "B1", pattern: "Present perfect: yet", explanation: "In negatives, yet comes at the end and means up to now.", sentence: "The post hasn't arrived ___ .", answer: "yet", options: ["yet", "already"], extra: [] },
  { id: "g-b1-x5-since-school", level: "B1", pattern: "for vs since", explanation: "since marks the starting point of a period.", sentence: "We've known each other ___ primary school.", answer: "since", options: ["since", "for"], extra: [] },
  { id: "g-b1-x6-for-ten-years", level: "B1", pattern: "for vs since", explanation: "for marks the length of the period.", sentence: "They've lived in Leeds ___ ten years.", answer: "for", options: ["for", "since"], extra: [] },
  { id: "g-b1-x7-cond1-miss", level: "B1", pattern: "First conditional", explanation: "The if-clause uses the present simple even for future meaning.", sentence: "If you ___ the bus, you'll be late. (miss)", answer: "miss", options: ["miss", "will miss"], extra: [] },
  { id: "g-b1-x8-unless-rains", level: "B1", pattern: "unless = if…not", explanation: "unless introduces the condition that stops the result happening.", sentence: "We'll go to the beach ___ it rains.", answer: "unless", options: ["unless", "if"], extra: [] },
  { id: "g-b1-x9-which-novel", level: "B1", pattern: "Relative clauses: which", explanation: "which (not who) refers to things in a non-defining clause.", sentence: "The novel, ___ I read last month, is being made into a film.", answer: "which", options: ["which", "who"], extra: [] },
  { id: "g-b1-x10-where-cafe", level: "B1", pattern: "Relative clauses: where", explanation: "where replaces preposition + which for places.", sentence: "This is the café ___ we first met.", answer: "where", options: ["where", "which"], extra: [] },
  { id: "g-b1-x11-whose-author", level: "B1", pattern: "Relative clauses: whose", explanation: "whose shows possession inside a relative clause.", sentence: "The author ___ book won the prize is from Cardiff.", answer: "whose", options: ["whose", "who"], extra: [] },
  { id: "g-b1-x12-cond2-would", level: "B1", pattern: "Second conditional", explanation: "If + past simple, would + base verb for imaginary situations.", sentence: "If I won the lottery, I ___ travel round the world.", answer: "would", options: ["would", "will"], extra: [] },
  { id: "g-b1-x13-cond2-passed", level: "B1", pattern: "Second conditional", explanation: "The imaginary if-clause uses the past simple (passed), not present.", sentence: "If she ___ the exam, she'd study medicine. (pass)", answer: "passed", options: ["passed", "passes"], extra: [] },
  { id: "g-b1-x14-didnt-use-to", level: "B1", pattern: "used to negatives", explanation: "The negative is didn't use to — the d of used disappears after did.", sentence: "I ___ like olives, but now I love them.", answer: "didn't use to", options: ["didn't use to", "didn't used to"], extra: [] },
  { id: "g-b1-x15-use-to-horse", level: "B1", pattern: "used to questions", explanation: "Questions use did … use to, without the final d.", sentence: "Did people ___ travel by horse?", answer: "use to", options: ["use to", "used to"], extra: [] },
  { id: "g-b1-x16-was-cooking", level: "B1", pattern: "Past continuous with while", explanation: "The longer background action takes the past continuous.", sentence: "While I ___ dinner, the phone rang. (cook)", answer: "was cooking", options: ["was cooking", "cooked"], extra: [] },
  { id: "g-b1-x17-was-walking", level: "B1", pattern: "Past continuous with when", explanation: "when + past simple interrupts a past continuous action.", sentence: "I ___ home when I saw the accident. (walk)", answer: "was walking", options: ["was walking", "walked"], extra: [] },
  { id: "g-b1-x18-while-during", level: "B1", pattern: "while vs during", explanation: "while introduces a clause with a subject and verb; during introduces a noun.", sentence: "He fell asleep ___ he was reading.", answer: "while", options: ["while", "during"], extra: [] },
  { id: "g-b1-x19-both-answers", level: "B1", pattern: "both / neither", explanation: "both + plural verb means the two together.", sentence: "___ answers are correct, so you get full marks.", answer: "Both", options: ["Both", "Neither"], extra: [] },
  { id: "g-b1-x20-neither-hotel", level: "B1", pattern: "both / neither", explanation: "neither means not one and not the other, with a singular verb.", sentence: "I tried two hotels, but ___ had a free room.", answer: "neither", options: ["neither", "both"], extra: [] },
  { id: "g-b1-x21-either-bus", level: "B1", pattern: "either (one of two)", explanation: "either means one or the other — it doesn't matter which.", sentence: "You can take ___ bus — they both stop at the station.", answer: "either", options: ["either", "neither"], extra: [] },
  { id: "g-b1-x22-indirect-station", level: "B1", pattern: "Indirect questions", explanation: "Indirect questions keep statement word order, so the verb follows the subject.", sentence: "Could you tell me where ___ ?", answer: "the station is", options: ["the station is", "is the station"], extra: [] },
  { id: "g-b1-x23-indirect-opens", level: "B1", pattern: "Indirect questions", explanation: "After do you know if, use normal statement order with the -s on the verb.", sentence: "Do you know if the shop ___ on Sundays? (open)", answer: "opens", options: ["opens", "open"], extra: [] },
  { id: "g-b1-x24-whether-tickets", level: "B1", pattern: "if / whether", explanation: "whether (not weather) introduces an embedded yes/no question.", sentence: "I'd like to know ___ the tickets include breakfast.", answer: "whether", options: ["whether", "weather"], extra: [] },
  { id: "g-b1-x25-cond1-wont-catch", level: "B1", pattern: "First conditional", explanation: "The result clause takes will/won't + base verb.", sentence: "If you don't hurry, we ___ the train. (catch — not)", answer: "won't catch", options: ["won't catch", "don't catch"], extra: [] },
  { id: "g-b1-x26-neither-parents", level: "B1", pattern: "neither of + plural", explanation: "neither of goes with a plural noun but takes a singular verb.", sentence: "___ of my parents speaks German, so I use a translator.", answer: "Neither", options: ["Neither", "None"], extra: [] },
  // B2 — passive, conditionals, reported speech, modals of deduction, wish/if only, past perfect, articles, causative, contrast linkers
  { id: "g-b2-x1-is-spoken", level: "B2", pattern: "Present simple passive", explanation: "The passive uses be + past participle; here the language is spoken by people.", sentence: "English ___ in over a hundred countries. (speak)", answer: "is spoken", options: ["is spoken", "speaks"], extra: [] },
  { id: "g-b2-x2-is-being-resurfaced", level: "B2", pattern: "Present continuous passive", explanation: "Ongoing passive actions use is/are being + past participle.", sentence: "The road ___ at the moment, so use the car park. (resurface)", answer: "is being resurfaced", options: ["is being resurfaced", "is resurfacing"], extra: [] },
  { id: "g-b2-x3-will-be-announced", level: "B2", pattern: "Future passive", explanation: "The future passive is will be + past participle.", sentence: "The results ___ by Friday. (announce — passive)", answer: "will be announced", options: ["will be announced", "will announce"], extra: [] },
  { id: "g-b2-x4-must-be-submitted", level: "B2", pattern: "Modal passive", explanation: "After a modal, the passive is be + past participle.", sentence: "Applications ___ before the end of the month. (must / submit)", answer: "must be submitted", options: ["must be submitted", "must submit"], extra: [] },
  { id: "g-b2-x5-were-bought", level: "B2", pattern: "Past simple passive", explanation: "The paintings are plural, so the passive needs were + past participle.", sentence: "The paintings ___ by a private collector last week. (buy)", answer: "were bought", options: ["were bought", "was bought"], extra: [] },
  { id: "g-b2-x6-would-have-caught", level: "B2", pattern: "Third conditional", explanation: "If + had + participle, would have + participle for unreal pasts.", sentence: "If we'd left earlier, we ___ the ferry. (catch)", answer: "would have caught", options: ["would have caught", "would catch"], extra: [] },
  { id: "g-b2-x7-would-have-helped", level: "B2", pattern: "Third conditional", explanation: "The result of an unreal past condition is would have + participle.", sentence: "If you had told me, I ___ you. (help)", answer: "would have helped", options: ["would have helped", "had helped"], extra: [] },
  { id: "g-b2-x8-werent-stubborn", level: "B2", pattern: "Second conditional with be", explanation: "In second conditionals, formal English prefers were for all persons.", sentence: "If he ___ so stubborn, we might reach an agreement. (not be)", answer: "weren't", options: ["weren't", "isn't"], extra: [] },
  { id: "g-b2-x9-asked-where-lived", level: "B2", pattern: "Reported questions", explanation: "Reported questions shift the tense back: live → lived.", sentence: "She asked me where I ___ . (live)", answer: "lived", options: ["lived", "live"], extra: [] },
  { id: "g-b2-x10-told-me", level: "B2", pattern: "tell vs say", explanation: "tell takes a person as its object (told me); say takes no person (said that).", sentence: "He ___ me that the meeting had been cancelled.", answer: "told", options: ["told", "said"], extra: [] },
  { id: "g-b2-x11-would-call", level: "B2", pattern: "Reported speech: will → would", explanation: "In reported speech will steps back to would.", sentence: "'I'll call you later.' → He said he ___ me later. (call)", answer: "would call", options: ["would call", "will call"], extra: [] },
  { id: "g-b2-x12-must-home", level: "B2", pattern: "Modals of deduction: must", explanation: "must expresses a confident deduction from evidence.", sentence: "The lights are on, so someone ___ be home.", answer: "must", options: ["must", "can't"], extra: [] },
  { id: "g-b2-x13-cant-dan", level: "B2", pattern: "Modals of deduction: can't", explanation: "can't expresses confident disbelief; mustn't expresses prohibition.", sentence: "That ___ be Dan — he's in Brazil this month.", answer: "can't", options: ["can't", "mustn't"], extra: [] },
  { id: "g-b2-x14-might-gym", level: "B2", pattern: "Modals of deduction: might", explanation: "might expresses a genuine possibility when you are unsure.", sentence: "I don't know where he is — he ___ be at the gym, but I doubt it.", answer: "might", options: ["might", "must"], extra: [] },
  { id: "g-b2-x15-wish-could", level: "B2", pattern: "wish + past (present regret)", explanation: "wish + could talks about an ability you lack now.", sentence: "I wish I ___ speak Japanese. (can)", answer: "could", options: ["could", "can"], extra: [] },
  { id: "g-b2-x16-if-only-had-studied", level: "B2", pattern: "if only + past perfect", explanation: "Regrets about the past take if only + had + participle.", sentence: "If only I ___ more at university. (study)", answer: "had studied", options: ["had studied", "studied"], extra: [] },
  { id: "g-b2-x17-wish-would-stop", level: "B2", pattern: "wish + would", explanation: "wish + would complains about someone or something else's behaviour.", sentence: "I wish it ___ stop raining.", answer: "would", options: ["would", "will"], extra: [] },
  { id: "g-b2-x18-had-already-started", level: "B2", pattern: "Past perfect", explanation: "The earlier of two past events takes had + participle.", sentence: "When we arrived, the film ___ already started.", answer: "had", options: ["had", "has"], extra: [] },
  { id: "g-b2-x19-had-lost", level: "B2", pattern: "Past perfect", explanation: "The key-loss happened before the being-upset, so use the past perfect.", sentence: "She was upset because she ___ her keys. (lose)", answer: "had lost", options: ["had lost", "lost"], extra: [] },
  { id: "g-b2-x20-the-netherlands", level: "B2", pattern: "Articles with country names", explanation: "Plural-form country names take the: the Netherlands, the UK.", sentence: "___ Netherlands is famous for tulips and canals.", answer: "The", options: ["The", "A"], extra: [] },
  { id: "g-b2-x21-play-the-violin", level: "B2", pattern: "the with musical instruments", explanation: "After play, musical instruments take the.", sentence: "She plays ___ violin beautifully.", answer: "the", options: ["the", "a"], extra: [] },
  { id: "g-b2-x22-have-tooth-checked", level: "B2", pattern: "Causative have", explanation: "have + object + past participle means someone else does it for you.", sentence: "You should ___ that tooth checked.", answer: "have", options: ["have", "make"], extra: [] },
  { id: "g-b2-x23-get-engine-start", level: "B2", pattern: "get something to do something", explanation: "get + object + to-infinitive means to make something succeed at doing it.", sentence: "I can't ___ this engine to start.", answer: "get", options: ["get", "have"], extra: [] },
  { id: "g-b2-x24-despite-traffic", level: "B2", pattern: "despite + noun phrase", explanation: "despite is followed by a noun or -ing, never a full clause.", sentence: "___ the heavy traffic, we arrived on time.", answer: "Despite", options: ["Despite", "Although"], extra: [] },
  { id: "g-b2-x25-whereas-partner", level: "B2", pattern: "whereas (contrast clauses)", explanation: "whereas joins two contrasting clauses and needs a subject and verb after it.", sentence: "I love cooking, ___ my partner would live on takeaway.", answer: "whereas", options: ["whereas", "despite"], extra: [] },
  { id: "g-b2-x26-in-spite-of-ill", level: "B2", pattern: "in spite of + -ing", explanation: "in spite of works like despite and is followed by a noun or -ing form.", sentence: "___ feeling ill, she went to work.", answer: "In spite of", options: ["In spite of", "Even though"], extra: [] },
  // C1 — inversion, clefts, participles, substitution/ellipsis, nominalisation, hedging modals, mixed conditionals, emphatic do, concessives
  { id: "g-c1-x1-rarely-is", level: "C1", pattern: "Negative inversion", explanation: "After a fronted negative adverbial like rarely, the subject and verb invert.", sentence: "Rarely ___ a first draft worth publishing.", answer: "is", options: ["is", "it is"], extra: [] },
  { id: "g-c1-x2-hardly-had", level: "C1", pattern: "Hardly had… when", explanation: "Hardly takes inversion with the past perfect, then when + past simple.", sentence: "Hardly ___ the door closed when the alarm went off.", answer: "had", options: ["had", "did"], extra: [] },
  { id: "g-c1-x3-not-only-did", level: "C1", pattern: "Not only … inversion", explanation: "Not only at the front triggers auxiliary inversion in the past.", sentence: "Not only ___ they apologise, they also refunded us in full.", answer: "did", options: ["did", "do"], extra: [] },
  { id: "g-c1-x4-little-did", level: "C1", pattern: "Little did + subject + verb", explanation: "Little as a fronted negative forces inversion: Little did she know…", sentence: "Little ___ she know what the contract contained.", answer: "did", options: ["did", "she did"], extra: [] },
  { id: "g-c1-x5-what-cleft", level: "C1", pattern: "What-cleft (pseudo-cleft)", explanation: "A what-cleft moves the emphasised element into focus before the verb.", sentence: "___ impressed the investors was the prototype, not the slides.", answer: "What", options: ["What", "That"], extra: [] },
  { id: "g-c1-x6-it-is-that", level: "C1", pattern: "It-cleft", explanation: "It is/was + focus + that frames the emphasised part of the sentence.", sentence: "It's the journey ___ matters, not the destination.", answer: "that", options: ["that", "what"], extra: [] },
  { id: "g-c1-x7-reason-why", level: "C1", pattern: "The reason why… is that", explanation: "The reason is followed by why, never by because.", sentence: "The reason ___ the launch failed is poor timing.", answer: "why", options: ["why", "because"], extra: [] },
  { id: "g-c1-x8-having-finished", level: "C1", pattern: "Perfect participle clause", explanation: "Having + participle marks an action completed before the main verb.", sentence: "___ the report, she circulated it to the board. (finish)", answer: "Having finished", options: ["Having finished", "Finished"], extra: [] },
  { id: "g-c1-x9-built-1901", level: "C1", pattern: "Past participle clause", explanation: "A past participle clause carries passive meaning: built by whom → it was built.", sentence: "___ in 1901, the lighthouse still guides ships today. (build)", answer: "Built", options: ["Built", "Building"], extra: [] },
  { id: "g-c1-x10-not-informed", level: "C1", pattern: "Negative participle clause", explanation: "The negative word goes before the participle, which stays passive here.", sentence: "___ by the delay, the manager called the depot. (not / inform)", answer: "Not informed", options: ["Not informed", "Not informing"], extra: [] },
  { id: "g-c1-x11-neither-have-i", level: "C1", pattern: "Neither + inversion", explanation: "Neither echoes a negative statement and inverts with the same auxiliary.", sentence: "'I've never trusted that supplier.' 'Neither ___ I.'", answer: "have", options: ["have", "did"], extra: [] },
  { id: "g-c1-x12-than-the-one", level: "C1", pattern: "Substitution with one", explanation: "one substitutes for a singular countable noun already mentioned.", sentence: "This laptop is slower than the ___ I borrowed.", answer: "one", options: ["one", "it"], extra: [] },
  { id: "g-c1-x13-as-did-trial", level: "C1", pattern: "as + do substitution", explanation: "as did … is an elegant way to say as … did without repeating the verb.", sentence: "The pilot scheme worked, as ___ the follow-up trial. (ellipsis of work)", answer: "did", options: ["did", "worked"], extra: [] },
  { id: "g-c1-x14-failure-noun", level: "C1", pattern: "Nominalisation", explanation: "Turning verbs into nouns (fail → failure) creates a denser, more formal style.", sentence: "The company's ___ of the deadline forced a rewrite. (fail)", answer: "failure", options: ["failure", "failing"], extra: [] },
  { id: "g-c1-x15-analysis-noun", level: "C1", pattern: "Nominalisation", explanation: "Formal writing prefers the noun analysis over the gerund analysing here.", sentence: "Careful ___ of the data revealed a clear trend. (analyse)", answer: "analysis", options: ["analysis", "analysing"], extra: [] },
  { id: "g-c1-x16-may-linked", level: "C1", pattern: "Hedging with may", explanation: "may presents a possibility, while must claims certainty — hedging weakens the claim.", sentence: "The decline ___ be linked to seasonal demand. (possibility)", answer: "may", options: ["may", "must"], extra: [] },
  { id: "g-c1-x17-would-appear", level: "C1", pattern: "it would appear that", explanation: "It would appear that distances the writer from the claim — formal hedging.", sentence: "It would ___ that the merger is being reconsidered. (appear)", answer: "appear", options: ["appear", "appears"], extra: [] },
  { id: "g-c1-x18-seems-to-be", level: "C1", pattern: "there seems to be", explanation: "there + seem + to be hedges the existence of something.", sentence: "There ___ to be some disagreement between the departments. (seem)", answer: "seems", options: ["seems", "seeming"], extra: [] },
  { id: "g-c1-x19-would-be-living", level: "C1", pattern: "Mixed conditional (past → present)", explanation: "A past condition with a present result uses would + infinitive now.", sentence: "If I had accepted that job, I ___ in Dublin now. (be — present result)", answer: "would be living", options: ["would be living", "would have lived"], extra: [] },
  { id: "g-c1-x20-would-have-met", level: "C1", pattern: "Mixed conditional (present → past)", explanation: "A present condition with a past result takes would have + participle.", sentence: "If she were more organised, she ___ the deadline last week. (meet)", answer: "would have met", options: ["would have met", "would meet"], extra: [] },
  { id: "g-c1-x21-does-reduce", level: "C1", pattern: "Emphatic does", explanation: "do/does before the main verb adds emphasis, contradicting doubt.", sentence: "The scheme ___ reduce emissions — the data proves it. (emphatic)", answer: "does", options: ["does", "do"], extra: [] },
  { id: "g-c1-x22-did-warn", level: "C1", pattern: "Emphatic did", explanation: "did + base verb stresses that the past action really happened.", sentence: "I ___ warn you about the fees, so don't blame me. (emphatic)", answer: "did", options: ["did", "do"], extra: [] },
  { id: "g-c1-x23-brilliant-as-she-is", level: "C1", pattern: "Concessive inversion with as", explanation: "Adjective + as + subject + be is a formal way of saying although she is…", sentence: "Brilliant ___ she is, she still gets nerves before matches.", answer: "as", options: ["as", "like"], extra: [] },
  { id: "g-c1-x24-while-accept", level: "C1", pattern: "While for concession", explanation: "While can mean although, introducing a full contrasting clause.", sentence: "___ I accept the findings, I dispute the recommendations.", answer: "While", options: ["While", "Despite"], extra: [] },
  { id: "g-c1-x25-should-you-require", level: "C1", pattern: "Inverted conditional with should", explanation: "Should you … replaces If you should … in formal conditionals.", sentence: "Should you ___ further information, please contact the office. (require)", answer: "require", options: ["require", "will require"], extra: [] },
  { id: "g-c1-x26-were-storm", level: "C1", pattern: "Inverted conditional with were", explanation: "Were + subject + to-infinitive replaces If … were to in formal conditionals.", sentence: "___ the storm to ease, the ferry would sail tonight.", answer: "Were", options: ["Were", "Would"], extra: [] },
  // C2 — mandative subjunctive, negative inversion, fronting, discourse tense/aspect, formal ellipsis, register modality
  { id: "g-c2-x1-insists-be", level: "C2", pattern: "Mandative subjunctive", explanation: "After insist, demand and require, the following clause uses the base form be.", sentence: "The committee insists that every application ___ reviewed independently. (be)", answer: "be", options: ["be", "is"], extra: [] },
  { id: "g-c2-x2-essential-be", level: "C2", pattern: "Mandative subjunctive", explanation: "It is essential that + base form is the formal subjunctive, not that … is.", sentence: "It is essential that every room ___ inspected before checkout.", answer: "be", options: ["be", "is"], extra: [] },
  { id: "g-c2-x3-require-sign", level: "C2", pattern: "Mandative subjunctive", explanation: "After require that, the verb stays in the base form with no -s.", sentence: "The guidelines require that each applicant ___ a declaration. (sign)", answer: "sign", options: ["sign", "signs"], extra: [] },
  { id: "g-c2-x4-lest-be", level: "C2", pattern: "lest + subjunctive", explanation: "lest is followed by the base form be in formal warnings.", sentence: "He lowered his voice lest he ___ overheard.", answer: "be", options: ["be", "was"], extra: [] },
  { id: "g-c2-x5-not-until-did", level: "C2", pattern: "Not until + inversion", explanation: "Fronted not until forces auxiliary inversion in the main clause.", sentence: "Not until the third audit ___ the discrepancy come to light.", answer: "did", options: ["did", "it did"], extra: [] },
  { id: "g-c2-x6-never-before-has", level: "C2", pattern: "Never before + inversion", explanation: "Never before inverts have and there: has there been.", sentence: "Never before ___ such opacity in the accounts.", answer: "has there been", options: ["has there been", "there has been"], extra: [] },
  { id: "g-c2-x7-under-no-circumstances", level: "C2", pattern: "Under no circumstances + inversion", explanation: "The fronted negative phrase inverts modal and subject: must this document leave.", sentence: "Under no circumstances ___ this document leave the building.", answer: "must", options: ["must", "can't"], extra: [] },
  { id: "g-c2-x8-such-was-demand", level: "C2", pattern: "Fronting: such was… that", explanation: "Such was + noun is the inverted form of The demand was so great that…", sentence: "Such ___ the demand that tickets sold out in minutes.", answer: "was", options: ["was", "were"], extra: [] },
  { id: "g-c2-x9-barely-did-he", level: "C2", pattern: "Fronting: barely + inversion", explanation: "Barely at the front triggers do-inversion in the past.", sentence: "Barely ___ a word during the whole hearing. (he / utter)", answer: "did he utter", options: ["did he utter", "he uttered"], extra: [] },
  { id: "g-c2-x10-equally-striking", level: "C2", pattern: "Fronting the complement", explanation: "Placing the adjective first is fronting; the verb still agrees with the noun.", sentence: "Equally striking ___ the absence of any independent review. (be)", answer: "was", options: ["was", "were"], extra: [] },
  { id: "g-c2-x11-had-broken", level: "C2", pattern: "Past perfect in discourse", explanation: "A past frame requires had + participle for an earlier event, never have.", sentence: "The board adjourned; by then, the press ___ the story. (already / break)", answer: "had broken", options: ["had broken", "has broken"], extra: [] },
  { id: "g-c2-x12-will-have-reached", level: "C2", pattern: "Future perfect with by", explanation: "By + future time point takes the future perfect for completion beforehand.", sentence: "By the time you read this, the jury ___ its verdict. (reach)", answer: "will have reached", options: ["will have reached", "will reach"], extra: [] },
  { id: "g-c2-x13-had-been-waiting", level: "C2", pattern: "Past perfect continuous", explanation: "Duration stretching to a past reference point takes had been + -ing.", sentence: "I ___ for your call all week — I'd almost given up. (wait)", answer: "had been waiting", options: ["had been waiting", "have been waiting"], extra: [] },
  { id: "g-c2-x14-will-be-watching", level: "C2", pattern: "Future continuous", explanation: "The future continuous presents an action as in progress at a set future time.", sentence: "At nine tonight I ___ the election coverage. (watch — in progress)", answer: "will be watching", options: ["will be watching", "will watch"], extra: [] },
  { id: "g-c2-x15-where-necessary", level: "C2", pattern: "Ellipsis: where + adjective", explanation: "Formal register deletes subject and be after where: where necessary = where it is necessary.", sentence: "Insert page breaks ___ ; it saves hours of manual work.", answer: "where necessary", options: ["where necessary", "where it necessary"], extra: [] },
  { id: "g-c2-x16-so-did-overheads", level: "C2", pattern: "So + inversion", explanation: "So + auxiliary + subject echoes a positive statement across sentences.", sentence: "Revenue doubled; ___ did the overheads.", answer: "So", options: ["So", "Such"], extra: [] },
  { id: "g-c2-x17-shall-applicants", level: "C2", pattern: "Formal obligation: shall", explanation: "In legal and formal registers, shall states binding obligation.", sentence: "Applicants ___ submit originals; photocopies will not be accepted. (obligation)", answer: "shall", options: ["shall", "might"], extra: [] },
  { id: "g-c2-x18-should-have-consulted", level: "C2", pattern: "should have + participle", explanation: "should have + participle criticises an action that did not happen.", sentence: "They ___ have consulted the unions first — that was the whole problem.", answer: "should", options: ["should", "can't"], extra: [] },
  { id: "g-c2-x19-so-be-it", level: "C2", pattern: "Formulaic subjunctive", explanation: "So be it is a fixed subjunctive phrase accepting a consequence.", sentence: "If the deadline passes, ___ — we start again.", answer: "so be it", options: ["so be it", "so it is"], extra: [] },
  { id: "g-c2-x20-come-what-may", level: "C2", pattern: "Formulaic subjunctive", explanation: "Come what may is a frozen subjunctive clause meaning whatever happens.", sentence: "Come what ___ , the expedition leaves on Monday.", answer: "may", options: ["may", "will"], extra: [] },
  { id: "g-c2-x21-had-been-frozen", level: "C2", pattern: "Backshift in reported clauses", explanation: "After a past reporting verb, have been shifts back to had been.", sentence: "He explained that the funds ___ frozen the previous week. (be)", answer: "had been", options: ["had been", "have been"], extra: [] },
  { id: "g-c2-x22-would-rent", level: "C2", pattern: "would for past habits", explanation: "In written narrative, would + base verb expresses repeated past actions.", sentence: "In those days, we ___ rent the same chalet every winter, whatever the snow.", answer: "would", options: ["would", "will"], extra: [] },
  { id: "g-c2-x23-did-so-aides", level: "C2", pattern: "Substitution: do so", explanation: "do so is the formal substitute for repeating a full verb phrase.", sentence: "The minister resigned, and two aides ___ within hours. (did the same)", answer: "did so", options: ["did so", "so did"], extra: [] },
  { id: "g-c2-x24-ordered-be-destroyed", level: "C2", pattern: "Mandative subjunctive", explanation: "After order that, the base form be is required in formal English.", sentence: "The regulator ordered that the data ___ destroyed. (be)", answer: "be", options: ["be", "was"], extra: [] },
  { id: "g-c2-x25-not-only-has", level: "C2", pattern: "Not only + inversion", explanation: "Not only at the front inverts has and the subject, keeping the participle after.", sentence: "Not only ___ the deadline slipped; the budget has doubled.", answer: "has", options: ["has", "did"], extra: [] },
  { id: "g-c2-x26-suffice-it-to-say", level: "C2", pattern: "Formulaic subjunctive", explanation: "Suffice it to say keeps the archaic subjunctive with no -s on the verb.", sentence: "___ it to say, the negotiations collapsed within a week.", answer: "Suffice", options: ["Suffice", "Suffices"], extra: [] },
];
